},
{
["key"] = "q:5481:accept:",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=5481\nevent=accept\nnpc=\ntitle=Gordo's Task\ntext<<\nMaster want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill graveyard.\n\n>>\nsum=1831759433\n",
},
{
["key"] = "q:5481:progress:10665",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=5481\nevent=progress\nnpc=10665 Junior Apothecary Holland\nkind=creature\nmodel=959310\ndisplays=9999\nsex=2\ncreature=Humanoid\ntitle=Gordo's Task\ntext<<\nWhere's that useless abomination? Either you have what I need or you'd best get out there and find it.\n>>\nsum=37765931\n",
},
{
["key"] = "q:365:progress:1518",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=365\nevent=progress\nnpc=1518 Apothecary Johaan\nkind=creature\nmodel=959310\ndisplays=1565\nsex=2\ncreature=Humanoid\ntitle=Fields of Grief\ntext<<\nDeathguard Simmer sent word that you were going to provide me with some much needed reagents.  Were you able to gather 10 pumpkins yet, $N?\n>>\nsum=1249322612\n",
},
{
["key"] = "q:383:progress:1515",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=383\nevent=progress\nnpc=1515 Executor Zygand\nkind=creature\nmodel=959310\ndisplays=1649\nsex=2\ncreature=Humanoid\ntitle=Vital Intelligence\ntext<<\nYes, what do you want?\n>>\nsum=18509601\n",
},
{
["key"] = "q:8:progress:5688",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=8\nevent=progress\nnpc=5688 Innkeeper Renee\nkind=creature\nmodel=997378\ndisplays=8190\nsex=3\ncreature=Humanoid\ntitle=A Rogue's Deal\ntext<<\nYes? Yes? What is it?\n\nThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name's Renee if you need anything at all.\n>>\nsum=75905823\n",
},
{
["key"] = "q:407:progress:1931",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=407\nevent=progress\nnpc=1931 Captured Scarlet Zealot\nkind=creature\nmodel=1011653\ndisplays=11428\nsex=2\ncreature=Humanoid\ntitle=Fields of Grief\ntext<<\nStay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your. . .\n\n. . .oh wait.  Is that food for me?  I am so hungry. . .\n>>\nsum=3337700\n",
},
{
["key"] = "q:99134:accept:1515",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70790\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=99134\nevent=accept\nnpc=1515 Executor Zygand\nkind=creature\nmodel=959310\nsex=2\ncreature=Humanoid\ntitle=Discipline\ntext<<\nYou are not a member of the Deathguard, and therefore have yet to disappoint me.\n\nAs a reward for your relative lack of incompetence, you shall punish those that have demonstrated such talents in excess.\n\nSwiftly now--$N, is it?--or I shall add your name to my ledger for someone else's reward.\n>>\nsum=1095940669\n",
},
{
["key"] = "q:92460:accept:251362",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92460\nevent=accept\nnpc=251362 Ailee Farheart\nkind=creature\nmodel=7478494\nsex=3\ncreature=Humanoid\ntitle=Coming of Age\ntext<<\nLook at you, bright eyed and ready for adventure! We need all the help we can get here in Thendal Village and your arrival is most welcome. I imagine you are brimming with nerves for what is to come. After all, you only get to come of age once in a lifetime.\n\nGo, seek out our village leader Rorian the Dayseeker at the entrance to the greatfather tree just west of here. He will get you started on your journey.\n>>\nsum=1156978732\n",
},
{
["key"] = "q:92460:complete:251361",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92460\nevent=complete\nnpc=251361 Rorian the Dayseeker\nkind=creature\nmodel=7478487\nsex=2\ncreature=Humanoid\ntitle=Coming of Age\ntext<<\nGale's greetings, $N. I am honored to bestow your coming of age relic today as you are recognized for the potential you bring to the shen'dorei. Our people have faced great hardship and persecution in our complex history.\n\nToday you are given this relic which is one of many held by those before you. Someday when your ashes are scattered to the winds it will pass to another to continue our tradition.\n\nAs you take this relic with you know that the winds of home will be with you wherever you travel.\n>>\nsum=783999005\n",
},
{
["key"] = "b:1803131747",
["envelope"] = "!SPOKEN1 readables\naddon=Spoken_Readables/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.3.0\npage=1803131747\nbook=Scribbled Note\nnumber=1\ntext<<\nGreetings, $N,\n\nYou've shown great promise as a $c, and I'd like to ensure that you receive proper guidance and training. \n\nThe rangers do a good job of keeping the wilds in check here in Thendal Grove, but beyond our borders... well, the same can't be said.\n\nCome find me near the center of the village as soon as you are able. The wilds are calling.\n\n-Tai'ree Farsight, $C Trainer\n>>\nsum=165864334\n",
},
{
["key"] = "q:93552:accept:251363",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=93552\nevent=accept\nnpc=251363 Dalia the Collector\nkind=creature\nsex=3\ncreature=Humanoid\ntitle=Harvesting Windstones\ntext<<\nWindstones are a critical resource on Zephras Isle as they contain the raw, concentrated energy of the winds themselves. The wind elementals who used to live here on Zephras with us vanished a number of years ago, and since then, the magic that sustains this island is slowly fading. Not without limitations, the windstones are still a reliable energy source, and are incredibly valuable to us.\n\nYou'll find raw windstones scattered around the grove. Think you can help me harvest them?\n>>\nsum=281241093\n",
},
{
["key"] = "q:92597:accept:251371",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92597\nevent=accept\nnpc=251371 Falorne Fallwind\nkind=creature\nmodel=7478487\nsex=2\ncreature=Humanoid\ntitle=Reading the Leylines\ntext<<\nHere in the elemental plane, we derive much of our arcane strength from leylines that still run through the ground under our feet. Of late, these leylines have begun to pierce the surface, giving us more direct and powerful access to these latent arcane energies.\n\nGo to the standing stones to the northeast. There is a leyline there. Tap into your birthright and draw in its energy.\n>>\nsum=1995406648\n",
},
{
["key"] = "q:94414:accept:257554",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=94414\nevent=accept\nnpc=257554 Halaan Hawk-Eye\nkind=creature\nmodel=7478487\nsex=2\ncreature=Humanoid\ntitle=The Anchors of Zephras\ntext<<\nGreetings, young $N. I oftentimes come here to look upon the ancient anchor pylon. Gifts from the spirits of the winds, they bind and sustain our island. Of late however, their magic has grown unstable and inconsistent.\n\nThey suffer no distress I can see. Their splendor has not changed.\n\nIf you'd like, I can lend you my gift to look upon them yourself.\n>>\nsum=1370109502\n",
},
{
["key"] = "q:92482:progress:251376",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92482\nevent=progress\nnpc=251376 Tai'ree Farsight\nkind=creature\nmodel=7478494\ndisplays=136976\nsex=3\ncreature=Humanoid\ntitle=The Way of the Hunter\ntext<<\n<Tai'ree nods at you curtly.>\n>>\nsum=527024528\n",
},
{
["key"] = "q:93552:progress:251363",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=93552\nevent=progress\nnpc=251363 Dalia the Collector\nkind=creature\nmodel=7478494\ndisplays=137697\nsex=3\ncreature=Humanoid\ntitle=Harvesting Windstones\ntext<<\nHello there, $c.\n>>\nsum=37494086\n",
},
{
["key"] = "q:92470:accept:251366",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92470\nevent=accept\nnpc=251366 Aetheen of the Gales\nkind=creature\nsex=3\ncreature=Humanoid\ntitle=Foul Matriarch\ntext<<\nRorian informed you that I've been watching you. I now offer you a test of resolve. However, be warned--it will send you into great danger.\n\nGo to the caves to the west. Thin out the ursera's numbers there, and find their matriarch, one the rangers call \"Urs'anah\". Put her down and bring me proof of her demise. Once you have done that, you will have taken an important step on your path.\n>>\nsum=2049139863\n",
},
{
["key"] = "q:92473:progress:257551",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92473\nevent=progress\nnpc=257551 Valreaa Valewind\nkind=creature\nmodel=1100258\ndisplays=139409\nsex=3\ncreature=Humanoid\ntitle=Aggressive Encroachment\ntext<<\nThe ursera have grown far more aggressive of late. I wonder what has changed to cause this shift in behavior?\n>>\nsum=1650574308\n",
},
{
["key"] = "q:92470:progress:251366",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92470\nevent=progress\nnpc=251366 Aetheen of the Gales\nkind=creature\nmodel=7478494\ndisplays=137339\nsex=3\ncreature=Humanoid\ntitle=Foul Matriarch\ntext<<\nWhat I ask of you is not easy, but you must be prepared for much greater challenges if you are to survive long enough to be of service to Zephras Isle.\n>>\nsum=941979260\n",
},
{
["key"] = "q:92596:accept:251903",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92596\nevent=accept\nnpc=251903 Rathiril Sunlance\nkind=creature\nmodel=7478487\nsex=2\ncreature=Humanoid\ntitle=The High Order\ntext<<\nThe aura of arcane energy that surrounds you is strong, even though you are not initiated as a mage. I am quite sure that you are going to be a capable adventurer, and your connection with our ancient magic will only ever be a boon to you even if you were to never utter a single word of power in spellcasting.\n\nCome, let us sit and speak some on my order, the nature of the arcane here on Zephras, and the plight of our people.\n>>\nsum=2020900180\n",
},
{
["key"] = "g:251903:2040845411",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nnpc=251903 Rathiril Sunlance\nkind=creature\nmodel=7478487\nsex=2\ncreature=Humanoid\ntext<<\nThe Cult? They are zealots and killers. They believe that we are being punished for some unspecific sin. The reality is that those that lead them are opportunists left over from a dubious order of so-called \"Priests\" of Al'Akir, the Windlord.\n\nThey now find themselves in a position to weaponize the fear of our people to consolidate their own power... and they have been quick to do so.\n>>\nsum=1430249001\n",
},
{
["key"] = "q:94413:accept:251903",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=94413\nevent=accept\nnpc=251903 Rathiril Sunlance\nkind=creature\nmodel=7478487\nsex=2\ncreature=Humanoid\ntitle=A Magical Affront\ntext<<\nThe recent emergence of the leylines on the surface of Zephras has been profound for our order. We have more direct and tangible access to the energies that permeate this place and it has increased our understanding of said magic greatly.\n\nThe Windshapers, however, view these emergences as scars on the land that must be \"healed\". This is an affront to our order and is something we simply cannot abide.\n\nGo to the leyline in the forest to the southwest and drive off the Windshapers you find there.\n>>\nsum=209657809\n",
},
{
["key"] = "q:93951:accept:251991",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=93951\nevent=accept\nnpc=251991 Taleen Shimmerthread\nkind=creature\nmodel=7478494\nsex=3\ncreature=Humanoid\ntitle=A Little Beauty\ntext<<\nThe hippogryphs that have taken up residence southwest of the village can be a nuisance, but they also present a rather unique opportunity to obtain their feathers. Many skyborne love to adorn their hair with vibrant plumes and the down feathers of a hippogryph are exceptionally vibrant and, more importantly, silky soft.\n\nIf you are heading that way, try and gather as many of the fallen feathers as you can from around their nesting grounds. Do be careful, as wild hippogryph are not tolerant of guests.\n>>\nsum=919901465\n",
},
{
["key"] = "q:92515:progress:251993",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92515\nevent=progress\nnpc=251993 Indari Sunseam\nkind=creature\nmodel=7478487\ndisplays=137059\nsex=2\ncreature=Humanoid\ntitle=The Problem With Prideclaws\ntext<<\nIf you ask me, I think Prideclaws are actually kind of cute. From a safe distance... and while standing behind someone holding a sword, of course.\n>>\nsum=1588663715\n",
},
{
["key"] = "g:257018:1408005658:f",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nnpc=257018 Naleeia Tattermend\nkind=creature\nmodel=7478494\ndisplays=140076\nsex=3\ncreature=Humanoid\ntext<<\nGales greetings, friend. Is there something I can help you with?\n>>\nsum=1219131427\n",
},
{
["key"] = "q:92553:progress:251905",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.3\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=92553\nevent=progress\nnpc=251905 Zerril Softbreeze\nkind=creature\nmodel=7478487\ndisplays=137343\nsex=2\ncreature=Humanoid\ntitle=Restocking the Larders\ntext<<\nNo matter how much things change here on Zephras and how uncertain things get, I always say that a pipe full of dried peacebloom and nice full belly is a comfort that can't be beat!\n>>\nsum=1040517155\n",
},
{
["key"] = "q:367:progress:1518",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.4-beta.1\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=367\nevent=progress\nnpc=1518 Apothecary Johaan\nkind=creature\nmodel=959310\ndisplays=1565\nsex=2\ncreature=Humanoid\ntitle=A New Plague\ntext<<\nHave you collected 5 vials of darkhound blood yet, $N? Time is fleeting!\n>>\nsum=643193455\n",
},
{
["key"] = "q:91282:accept:246152",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.4-beta.1\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.5.0\nquest=91282\nevent=accept\nnpc=246152 Shari Stilwell\nkind=creature\nmodel=997378\nsex=3\ncreature=Humanoid\ntitle=A Second Home\ntext<<\nIt is encouraging to see my newly risen brothers and sisters thrive as you have. It is only through community and shared faith that we can truly realize our full potential however, and to that end we've begun to form a new paladin order right here in Tirisfal. \n\nIf you wish to learn more, you should visit our monastery on the edge of the Whispering Woods. It is called Bandarion Keep. It's on the bluffs just northwest of the Solliden Farmstead, and should be hard to miss.\n>>\nsum=266705266\n",
},
{
["key"] = "q:86784:progress:265812",
